/*
 * Service worker kill switch.
 *
 * The Chirpy theme caches every page in a service worker, which keeps serving
 * the old version of the site after a deploy until the visitor clicks the
 * "Update" toast. PWA is now disabled, so this file replaces the theme's
 * service worker: it deletes all caches, unregisters itself and reloads any
 * open tabs. After this runs once, the site always loads from the network.
 */
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});
